const input = $input.first().json || {};
const execution = input.execution || {};
const workflow = input.workflow || {};
const error = execution.error || {};
return [{ json: {
  executionId: String(execution.id || 'unknown'),
  workflowId: workflow.id ? String(workflow.id) : null,
  workflowName: String(workflow.name || 'unknown'),
  lastNode: execution.lastNodeExecuted ? String(execution.lastNodeExecuted) : null,
  errorMessage: String(error.message || execution.errorMessage || 'Unknown n8n execution error').slice(0, 2000),
  errorStack: error.stack ? String(error.stack).slice(0, 8000) : null,
  executionUrl: execution.url ? String(execution.url) : null,
  mode: execution.mode ? String(execution.mode) : null
} }];
